My repro:
def my_compiler(jit_mod, example_inputs):
    try:
        shape_list = [(f"inp_{idx}", i.shape) for idx, i in enumerate(example_inputs)
        graph_input = list(jit_mod.graph.inputs())[1:]
        new_input_infos = []
        for inp in shape_list:
            if (
                not isinstance(inp[1], tuple)
                or len(inp[1]) == 0
                or not isinstance(inp[1][-1], str)
            ):
                new_input_infos.append((inp[0], (inp[1], "float32")))
            else:
                new_input_infos.append(inp)
        for (name, info), gi in zip(new_input_infos, graph_input):
            pt_type = gi.type()
            shape, itype = info
            if pt_type.dim() != len(shape):
                raise Exception("input mismatch")

When I ran the above repro like python3 benchmarks/torchbench.py --only hf_BigBird --backend my_compiler, the error message looks like:
# name -> inp_0
# gi - > _stack0.1 defined in (%self : __torch__.torch.fx.graph_module.___torch_mangle_17.GraphModule, %_stack0.1 : Long(12, 62, 3, strides=[186, 3, 1], requires_grad=0, device=cpu), %query_layer : Float(1, 12, 4096, 64, strides=[3145728, 64, 768, 1], requires_grad=0, device=cpu), %key_layer : Float(1, 12, 4096, 64, strides=[3145728, 64, 768, 1], requires_grad=0, device=cpu), %value_layer : Float(1, 12, 4096, 64, strides=[3145728, 64, 768, 1], requires_grad=0, device=cpu), %band_mask : Float(1, 1, 60, 64, 192, strides=[737280, 737280, 12288, 192, 1], requires_grad=0, device=cpu), %from_mask : Float(1, 1, 4096, 1, strides=[4096, 4096, 1, 1], requires_grad=0, device=cpu), %to_mask : Float(1, 1, 1, 4096, strides=[4096, 4096, 4096, 1], requires_grad=0, device=cpu), %from_blocked_mask : Float(1, 64, 64, strides=[4096, 64, 1], requires_grad=0, device=cpu), %to_blocked_mask : Float(1, 64, 64, strides=[4096, 64, 1], requires_grad=0, device=cpu) = prim::Param()
)
# shape -> torch.Size([1, 12, 62, 3])
# pt_type.dim() -> 3
# pt_type.sizes() -> [12, 62, 3]

It seems like the size of input inp_0 in example_inputs is [1,12,62,3] which is different from its size ([12,62,3]) in jit_mod.graph.inputs(). I wonder which input size should the compiler pick here. Thanks!

When the output of a function is a functionalization tensor and saved for backward, we call .tensor_data() which calls shallow_copy_and_detach underneath.
Repro:
import torch
from torch.testing._internal.logging_tensor import LoggingTensor

inp = torch._to_functional_tensor(LoggingTensor(torch.randn(2, 2))).requires_grad_(True)
inp.exp()
Changing exp to sigmoid which saves output for bw also segfaults, but changing sin which saves input for bw is OK
